#!/bin/sh
set -eu
cd /workspace
cat > /workspace/.acceptance-removeheaders.test.js <<'EOF'
'use strict'
const { test } = require('node:test')
const assert = require('node:assert/strict')
const Fastify = require('.')

test('removeHeaders removes multiple headers case-insensitively and returns same reply', async () => {
  const app = Fastify()
  app.get('/', (req, reply) => {
    reply.header('X-Foo', 'foo')
    reply.header('X-Bar', 'bar')
    reply.header('X-Baz', 'baz')
    const ret = reply.removeHeaders(['x-foo', 'X-BAR'])
    assert.strictEqual(ret, reply, 'must return same reply instance')
    assert.strictEqual(reply.getHeader('x-foo'), undefined)
    assert.strictEqual(reply.getHeader('x-bar'), undefined)
    assert.strictEqual(reply.getHeader('x-baz'), 'baz')
    reply.send()
  })
  await app.ready()
  const res = await app.inject({ method: 'GET', url: '/' })
  assert.equal(res.statusCode, 200)
  assert.equal(res.headers['x-foo'], undefined)
  assert.equal(res.headers['x-bar'], undefined)
  assert.equal(res.headers['x-baz'], 'baz')
  await app.close()
})

test('removeHeaders empty array is a no-op and returns same reply', async () => {
  const app = Fastify()
  app.get('/', (req, reply) => {
    reply.header('x-foo', 'foo')
    const ret = reply.removeHeaders([])
    assert.strictEqual(ret, reply)
    assert.strictEqual(reply.getHeader('x-foo'), 'foo')
    reply.send()
  })
  await app.ready()
  const res = await app.inject({ method: 'GET', url: '/' })
  assert.equal(res.headers['x-foo'], 'foo')
  await app.close()
})

test('removeHeaders duplicate and missing names are harmless', async () => {
  const app = Fastify()
  app.get('/', (req, reply) => {
    reply.header('x-foo', 'foo')
    const ret = reply.removeHeaders(['x-foo', 'x-foo', 'x-missing', 'X-FOO'])
    assert.strictEqual(ret, reply)
    assert.strictEqual(reply.getHeader('x-foo'), undefined)
    reply.send()
  })
  await app.ready()
  const res = await app.inject({ method: 'GET', url: '/' })
  assert.equal(res.headers['x-foo'], undefined)
  await app.close()
})

test('removeHeaders non-array input throws TypeError and leaves headers unchanged', async () => {
  const app = Fastify()
  app.get('/', (req, reply) => {
    reply.header('x-foo', 'foo')
    assert.throws(() => reply.removeHeaders('x-foo'), TypeError)
    assert.throws(() => reply.removeHeaders({ 0: 'x-foo' }), TypeError)
    assert.throws(() => reply.removeHeaders(42), TypeError)
    assert.throws(() => reply.removeHeaders(null), TypeError)
    assert.strictEqual(reply.getHeader('x-foo'), 'foo', 'headers unchanged after invalid input')
    reply.send()
  })
  await app.ready()
  const res = await app.inject({ method: 'GET', url: '/' })
  assert.equal(res.statusCode, 200)
  assert.equal(res.headers['x-foo'], 'foo')
  await app.close()
})

test('removeHeaders non-string element throws TypeError and leaves headers unchanged (validate-before-mutate)', async () => {
  const app = Fastify()
  app.get('/', (req, reply) => {
    reply.header('x-foo', 'foo')
    reply.header('x-bar', 'bar')
    assert.throws(() => reply.removeHeaders(['x-foo', 123]), TypeError)
    assert.throws(() => reply.removeHeaders(['x-foo', null]), TypeError)
    assert.throws(() => reply.removeHeaders(['x-foo', undefined]), TypeError)
    assert.throws(() => reply.removeHeaders(['x-foo', { bad: true }]), TypeError)
    assert.strictEqual(reply.getHeader('x-foo'), 'foo', 'validate-before-mutate: x-foo preserved')
    assert.strictEqual(reply.getHeader('x-bar'), 'bar', 'validate-before-mutate: x-bar preserved')
    reply.send()
  })
  await app.ready()
  const res = await app.inject({ method: 'GET', url: '/' })
  assert.equal(res.statusCode, 200)
  assert.equal(res.headers['x-foo'], 'foo')
  assert.equal(res.headers['x-bar'], 'bar')
  await app.close()
})

test('removeHeaders chains fluently with removeHeader and returns same reply', async () => {
  const app = Fastify()
  app.get('/', (req, reply) => {
    reply.header('x-foo', 'foo')
    reply.header('x-bar', 'bar')
    const ret = reply.removeHeader('x-foo').removeHeaders(['x-bar'])
    assert.strictEqual(ret, reply)
    assert.strictEqual(reply.getHeader('x-foo'), undefined)
    assert.strictEqual(reply.getHeader('x-bar'), undefined)
    reply.send()
  })
  await app.ready()
  const res = await app.inject({ method: 'GET', url: '/' })
  assert.equal(res.headers['x-foo'], undefined)
  assert.equal(res.headers['x-bar'], undefined)
  await app.close()
})
EOF
node --test --test-reporter=spec /workspace/.acceptance-removeheaders.test.js
echo "PASS: removeHeaders behavior"

